if 'id="hq"' not in s: s = s.replace('<a class="btn ghost" href="/audit">Check your site in 60 seconds</a></div>', '<a class="btn ghost" href="/audit">Check your site in 60 seconds</a></div>\n      ' + HQ, 1)
# 2. order: the problem first (where the jobs go, the numbers), then the audit
def block(sid):
    a = s.index(f'<section id="{sid}"'); b = s.index('</section>', a) + len('</section>'); return a, b
ia, ib = block('inside'); la, lb = block('leaks'); pa, pb = block('problem')
if ia < la:
    inside = s[ia:la]; s = s[:ia] + s[la:pb] + '\n' + inside.rstrip() + s[pb:]
