LAZY = '''<script>(function(){function add(src){var s=document.createElement('script');s.type='module';s.src=src;document.head.appendChild(s)}var idle=window.requestIdleCallback||function(f){setTimeout(f,200)};function when(sel,src,ms){var done=false,el=document.querySelector(sel);function go(){if(done)return;done=true;add(src)}if(el&&'IntersectionObserver' in window)new IntersectionObserver(function(e,o){if(e[0].isIntersecting){o.disconnect();go()}},{rootMargin:'60% 0px'}).observe(el);var late=function(){setTimeout(function(){idle(go)},ms)};if(document.readyState==='complete')late();else addEventListener('load',late)}when('#inside','/assets/cinder-unit.js',2600);when('#build','/assets/cinder-objects.js',4200)})();</script>'''
for tag in ('<script type="module" src="/assets/cinder-objects.js"></script>\n', '<script type="module" src="/assets/cinder-unit.js"></script>\n'): s = s.replace(tag, '')
if 'cinder-unit.js\',2600' not in s: s = s.replace('<script type="module" src="/assets/cinder-flow.js"></script>', '<script type="module" src="/assets/cinder-flow.js"></script>\n' + LAZY, 1)
